target.css:
:root {
  --ink: #25352d;
  --muted: #718178;
  --paper: #fffdf7;
  --line: #dce5d9;
  --leaf: #377b58;
  --leaf-pale: #e5f1e6;
  --sun: #f3c960;
  --sun-pale: #fff3ce;
}

.plan-card {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.plan-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow,
.task-label {
  margin: 0 0 4px;
  color: var(--leaf);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
  letter-spacing: -0.5px;
}

.subtitle {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.weather {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 2px 0 0;
  padding: 7px 9px;
  border-radius: 10px;
  background: var(--sun-pale);
  font-size: 13px;
}

.plan-main {
  display: grid;
  grid-template-columns: 178px 1fr;
  gap: 18px;
  padding: 14px 18px;
}

.week-panel {
  margin: 0;
  padding-right: 18px;
  border-right: 1px solid var(--line);
}

figcaption {
  margin-bottom: 10px;
  font-size: 12px;
  font-weight: 700;
}

.week-grid,
.task-list {
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
}

.week-grid {
  justify-content: space-between;
}

.week-grid li {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.week-grid b {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 50%;
  background: var(--leaf-pale);
  color: var(--leaf);
  font-size: 10px;
}

.week-grid .today {
  background: var(--leaf);
  color: var(--paper);
}

.week-grid .done {
  background: var(--sun);
  color: var(--ink);
}

.tasks {
  min-width: 0;
}

.task-list {
  flex-direction: column;
  gap: 8px;
}

.task-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}

.plant-icon {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 9px;
  background: var(--leaf-pale);
  font-size: 15px;
}

.task-list strong,
.task-list small {
  display: block;
}

.task-list small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
}

.task-list em {
  margin-left: auto;
  color: var(--leaf);
  font-size: 11px;
  font-style: normal;
  font-weight: 800;
}

.plan-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  background: var(--leaf-pale);
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
}

.plan-footer span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.plan-footer i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--leaf);
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--leaf);
  color: var(--paper);
  font-size: 11px;
  font-weight: 800;
}

